right:
@import 'c/ihStyles';

.filters {
    flex-direction: row;
    flex-wrap: wrap;
    align-items: flex-end;
}
.filters lightning-combobox {
    min-width: 180px;
}
.filters .date, .filters .days {
    width: 170px;
}
.grow {
    flex: 1 1 320px;
}
.layout {
    display: flex;
    flex-wrap: wrap;
    gap: 16px;
    align-items: flex-start;
}
.list-card {
    flex: 1 1 640px;
    min-width: 0;
}
.detail {
    flex: 0 1 460px;
    min-width: 320px;
    position: sticky;
    top: 12px;
    max-height: calc(100vh - 140px);
    overflow: auto;
}
.ih-table {
    min-width: 980px;
}
.row {
    cursor: pointer;
}
.row_on td {
    background: var(--ih-brand-soft) !important;
}
.more {
    display: flex;
    justify-content: center;
    padding: 12px;
}
.hint {
    text-align: center;
    padding: 0 12px 12px;
}
.kv-row {
    display: contents;
}
.body {
    display: flex;
    flex-direction: column;
    gap: 4px;
}
